Here's a simple example using Python and the `json` module. I'll assume we're using a simple schema with a single object:
```json
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Example Data",
  "type": "object",
  "properties": {
    "name": {"type": "string"},
    "value": {"type": "number"}
  },
  "required": ["name", "value"]
}
```
In Python:
```python
import json

data = {
    'name': 'example',
    'value': 42
}

schema = {
    '$schema': 'http://json-schema.org/draft-07/schema#',
    'title': 'Example Data',
    'type': 'object',
    'properties': {
        'name': {'type':'string'},
        'value': {'type': 'number'}
    },
   'required': ['name', 'value']
}

def validate(data, schema):
    try:
        json.dumps(data, check_circular=False, default=str, indent=4)
        # We've passed validation
        return data
    except ValueError as e:
        # validation failed
        print(f"Validation failed: {e}")
        return None

validated = validate(data, schema)
if validated:
    print(json.dumps(validated, indent=4))
```
In JavaScript using the `ajv` library (install with `npm install ajv`):
```javascript
const Ajv = require('ajv');
const ajv = new Ajv();

const schema = {
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Example Data",
  "type": "object",
  "properties": {
    "name": {"type": "string"},
    "value": {"type": "number"}
  },
  "required": ["name", "value"]
};

const data = {
  name: 'example',
  value: 42
};

const valid = ajv.validate(schema, data);
if (!valid) {
  console.error(ajv.errors);
}
console.log(JSON.stringify(data, null, 4));
```
